import jsonimport osfrom pathlib import Pathfrom typing import List, Optional, Union, Dict, Literalimport base64import mimetypesimport ioimport PILimport PIL.Imageimport torchfrom torch.utils.data import Datasetimport clipDILATION = 0.7PAD_CROP = Truedef expand2square(pil_img, background_color=(0, 0, 0)):    width, height = pil_img.size    if width == height:        return pil_img    elif width > height:        result = PIL.Image.new(pil_img.mode, (width, width), background_color)        result.paste(pil_img, (0, (width - height) // 2))        return result    else:        result = PIL.Image.new(pil_img.mode, (height, height), background_color)        result.paste(pil_img, ((height - width) // 2, 0))        return resultclass VAWDataset(Dataset):    def __init__(self, transform=None, image_dir='./data_CIR/GeneCIS/Visual_Genome/VG_All/',                 blip_transform=None) -> None:        super().__init__()        self.image_dir = image_dir        self.transform = transform        self.blip_transform = blip_transform        self.dilate = DILATION        self.pad_crop = PAD_CROP    def load_cropped_image(self, img):        image_id = img['image_id']        bbox = img['instance_bbox']        # Get image        path = os.path.join(self.image_dir, f'{image_id}.jpg')        im = PIL.Image.open(path).convert('RGB')        im_width, im_height = im.size        width = bbox[2]  # Width of bounding box        height = bbox[3]  # Height of bounding box        if self.dilate:            orig_left, orig_top = bbox[0], bbox[1]            left, top = max(0, orig_left - self.dilate * width), max(0, orig_top - self.dilate * height)            right, bottom = min(im_width, left + (1 + self.dilate) * width), min(im_height,                                                                                 top + (1 + self.dilate) * height)        else:            left, top = bbox[0], bbox[1]            right, bottom = bbox[0] + width, bbox[1] + height        im = im.crop((left, top, right, bottom))        if self.pad_crop:            if im.mode == 'L':                bg_color = (0,)            else:                bg_color = (0, 0, 0)            im = expand2square(im, bg_color)        return im    def load_sample(self, sample):        im = self.load_cropped_image(sample)        if self.transform is not None:            im = self.transform(im)            return im        else:            # Existing code to save and encode the image            with io.BytesIO() as output:                im.save(output, format="PNG")                encoded_image = base64.b64encode(output.getvalue()).decode("ascii")            image_url = f"data:image/png;base64," + encoded_image            return im    def load_blip_sample(self, sample):        im = self.load_cropped_image(sample)        return imclass VAWValSubset(VAWDataset):    def __init__(self, val_split_path, data_split, preprocess, tokenizer=None, *args, **kwargs) -> None:        super().__init__(*args, **kwargs)        with open(val_split_path) as f:            val_samples = json.load(f)        self.val_samples = val_samples        self.tokenizer = tokenizer        self.data_split = data_split        self.preprocess = preprocess    def __getitem__(self, index):        """        Follow same return signature as CIRRSubset            (Except for returning reference object at the end)        """        sample = self.val_samples[index]        orig_reference = sample['reference']        reference_name = orig_reference['image_id']        target = sample['target']        gallery = sample['gallery']        caption = sample['condition']        # if "change" in self.data_split:        #     caption = f"Change an attribute of {caption}"        # elif "focus" in self.data_split:        #     caption = f"Focus on the attribute of {caption}"        # print(caption)        reference = self.load_sample(orig_reference)        blip_ref_img = self.load_blip_sample(orig_reference)        blip_ref_img = self.preprocess(blip_ref_img)        if "change" in self.data_split:            pseudo_gallery_path = [                os.path.join('./data_CIR/GeneCIS/gallery/change_attribute_gallery_target_img/',                             f'{str(index)}', f'{str(i + 1)}.png') for i in range(len(gallery))]            pseudo_gallery = [self.preprocess(PIL.Image.open(i)) for i in pseudo_gallery_path]            pseudo_target_database_path = os.path.join(                './data_CIR/GeneCIS/gallery/change_attribute_gallery_target_img/', f'{str(index)}', '0.png')            pseudo_target_database = self.preprocess(PIL.Image.open(pseudo_target_database_path))            pseudo_gallery = torch.stack(pseudo_gallery)            synthetic_img = torch.cat([pseudo_target_database.unsqueeze(0), pseudo_gallery])        elif "focus" in self.data_split:            pseudo_gallery_path = [                os.path.join('./data_CIR/GeneCIS/gallery/focus_attribute_gallery_target_img/',                             f'{str(index)}', f'{str(i + 1)}.png') for i in range(len(gallery))]            pseudo_gallery = [self.preprocess(PIL.Image.open(i)) for i in pseudo_gallery_path]            pseudo_target_database_path = os.path.join(                './data_CIR/GeneCIS/gallery/focus_attribute_gallery_target_img/', f'{str(index)}', '0.png')            pseudo_target_database = self.preprocess(PIL.Image.open(pseudo_target_database_path))            pseudo_gallery = torch.stack(pseudo_gallery)            synthetic_img = torch.cat([pseudo_target_database.unsqueeze(0), pseudo_gallery])        if "change" in self.data_split:            mental_img_path = os.path.join(                './data_CIR/GeneCIS/reference_pseodu_target_images/change_attribute_edit_3',                f'{index}.png')            mental_img = self.preprocess(PIL.Image.open(mental_img_path))            mental_img_des_path = os.path.join(                './data_CIR/GeneCIS/reference_pseodu_target_images/change_attribute_edit_des_3',                f'{index}.txt')            with open(mental_img_des_path, 'r') as f:                mental_img_des = f.read()        elif "focus" in self.data_split:            mental_img_path = os.path.join(                './data_CIR/GeneCIS/reference_pseodu_target_images/focus_attribute_edit_3',                f'{index}.png')            mental_img = self.preprocess(PIL.Image.open(mental_img_path))            mental_img_des_path = os.path.join(                './data_CIR/GeneCIS/reference_pseodu_target_images/focus_attribute_edit_des_3',                f'{index}.txt')            with open(mental_img_des_path, 'r') as f:                mental_img_des = f.read()        gallery = [self.preprocess(self.load_sample(i)) for i in gallery]        gallery = torch.stack(gallery)        target = self.preprocess(self.load_sample(target))        gallery_and_target = torch.cat([target.unsqueeze(0), gallery])        if self.tokenizer is not None:            caption = self.tokenizer(caption)        # By construction, target_rank = 0        return {            'caption': caption,            'reference_image': blip_ref_img,            'reference_name': reference_name,            'mental_img': mental_img,            'mental_img_des': mental_img_des,            'synthetic_img': synthetic_img,            'gallery_and_target': gallery_and_target,            'target_rank': 0        }    def __len__(self):        return len(self.val_samples)class COCODataset(Dataset):    def __init__(self, transform=None, blip_transform=None,                 root_dir='./data_CIR/GeneCIS/val2017/') -> None:        super().__init__()        self.root_dir = root_dir        self.transform = transform        self.blip_transform = blip_transform    def load_blip_sample(self, sample):        val_img_id = sample['val_image_id']        fpath = str(os.path.join(self.root_dir, f'{(12 - len(str(val_img_id))) * "0"}{val_img_id}.jpg'))        if self.blip_transform is not None:            orig_img = PIL.Image.open(fpath)            img = self.blip_transform(orig_img)            return img        else:            return fpath    def load_sample(self, sample):        val_img_id = sample['val_image_id']        fpath = str(os.path.join(self.root_dir, f'{(12 - len(str(val_img_id))) * "0"}{val_img_id}.jpg'))        if self.transform is not None:            orig_img = PIL.Image.open(fpath)            img = self.transform(orig_img)            return img        else:            return fpathclass COCOValSubset(COCODataset):    def __init__(self, val_split_path, data_split, preprocess, tokenizer=None, *args, **kwargs) -> None:        super().__init__(*args, **kwargs)        with open(val_split_path) as f:            val_samples = json.load(f)        self.val_samples = val_samples        self.tokenizer = tokenizer        self.data_split = data_split        self.preprocess = preprocess    def __getitem__(self, index):        """        Follow same return signature as CIRRSubset        """        sample = self.val_samples[index]        orig_reference = sample['reference']        target = sample['target']        gallery = sample['gallery']        reference_name = orig_reference['val_image_id']        # "change" in self.data_split:        if "change" in self.data_split:            # caption = f"Change an object of {caption}"            caption = sample['condition']        elif "focus" in self.data_split:            caption = sample['condition']            caption = f"Focus on the object of {caption}"        pseudo_gallery_path = [            os.path.join('./data_CIR/GeneCIS/gallery/val2017_img',                         f'{(12 - len(str(i["val_image_id"]))) * "0"}{i["val_image_id"]}.png') for i in            gallery]        pseudo_gallery = [self.preprocess(PIL.Image.open(i)) for i in pseudo_gallery_path]        pseudo_target_database_path = os.path.join('./data_CIR/GeneCIS/gallery/val2017_img',                                                   f'{(12 - len(str(target["val_image_id"]))) * "0"}{target["val_image_id"]}.png')        pseudo_target_database = self.preprocess(PIL.Image.open(pseudo_target_database_path))        pseudo_gallery = torch.stack(pseudo_gallery)        synthetic_img = torch.cat([pseudo_target_database.unsqueeze(0), pseudo_gallery])        if "change" in self.data_split:            mental_img_path = os.path.join(                './data_CIR/GeneCIS/reference_pseodu_target_images/change_object_edit_3',                f'{index}.png')            mental_img = self.preprocess(PIL.Image.open(mental_img_path))            mental_img_des_path = os.path.join(                './data_CIR/GeneCIS/reference_pseodu_target_images/change_object_edit_des_3',                f'{index}.txt')            with open(mental_img_des_path, 'r') as f:                mental_img_des = f.read()        elif "focus" in self.data_split:            mental_img_path = os.path.join(                './data_CIR/GeneCIS/reference_pseodu_target_images/focus_object_edit_3',                f'{index}.png')            mental_img = self.preprocess(PIL.Image.open(mental_img_path))            mental_img_des_path = os.path.join(                './data_CIR/GeneCIS/reference_pseodu_target_images/focus_object_edit_des_3',                f'{index}.txt')            with open(mental_img_des_path, 'r') as f:                mental_img_des = f.read()        reference = self.load_sample(orig_reference)        target = self.load_sample(target)        target = self.preprocess(PIL.Image.open(target))        # blip_ref_img = self.load_blip_sample(orig_reference)        ref_img = self.preprocess(PIL.Image.open(reference))        gallery = [self.preprocess(PIL.Image.open(self.load_sample(i))) for i in gallery]        gallery = torch.stack(gallery)        gallery_and_target = torch.cat([target.unsqueeze(0), gallery])        if self.tokenizer is not None:            caption = self.tokenizer(caption)        if self.tokenizer is not None:            caption = self.tokenizer(caption)        # By construction, target_rank = 0        return {            'caption': caption,            'reference_image': ref_img,            'reference_name': reference_name,            'mental_img': mental_img,            'mental_img_des': mental_img_des,            'synthetic_img': synthetic_img,            'gallery_and_target': gallery_and_target,            'target_rank': 0        }    def __len__(self):        return len(self.val_samples)class FashionIQDataset(Dataset):    """    FashionIQ dataset class for PyTorch.    The dataset can be used in 'relative' or 'classic' mode:        - In 'classic' mode the dataset yield :a dict with keys ['image', 'image_name']        - In 'relative' mode the dataset yield dict with keys:            - ['reference_image', 'reference_name', 'target_image', 'target_name', 'relative_captions'] when             split in ['train', 'val']            - ['reference_image', 'reference_name', 'relative_captions'] when split == test    """    def __init__(self, dataset_path: Union[Path, str], split: Literal['train', 'val', 'test'], dress_types: List[str],                 mode: Literal['relative', 'classic'], preprocess: callable, no_duplicates: Optional[bool] = False):        """        :param dataset_path: path to the FashionIQ dataset        :param split: dataset split, should be in ['train, 'val', 'test']        :param dress_types: list of fashionIQ categories, each category should be in ['dress', 'shirt', 'toptee']        :param mode: dataset mode, should be in ['relative', 'classic']:            - In 'classic' mode the dataset yield a dict with keys ['image', 'image_name']            - In 'relative' mode the dataset yield dict with keys:                - ['reference_image', 'reference_name', 'target_image', 'target_name', 'relative_captions']                 when split in ['train', 'val']                - ['reference_image', 'reference_name', 'relative_captions'] when split == test        :param preprocess: function which preprocesses the image        :param no_duplicates: if True, the dataset will not yield duplicate images in relative mode, does not affect classic mode        """        dataset_path = Path(dataset_path)        self.dataset_path = dataset_path        self.mode = mode        self.dress_types = dress_types        self.split = split        self.no_duplicates = no_duplicates        # Validate the inputs        if mode not in ['relative', 'classic']:            raise ValueError("mode should be in ['relative', 'classic']")        if split not in ['test', 'train', 'val']:            raise ValueError("split should be in ['test', 'train', 'val']")        for dress_type in dress_types:            if dress_type not in ['dress', 'shirt', 'toptee']:                raise ValueError("dress_type should be in ['dress', 'shirt', 'toptee']")        self.preprocess = preprocess        # get triplets made by (reference_image, target_image, a pair of relative captions)        self.triplets: List[dict] = []        for dress_type in dress_types:            with open(dataset_path / 'FASHIONIQ' / 'captions' / f'cap.{dress_type}.{split}_merge_caption.json') as f:                self.triplets.extend(json.load(f))        # Remove duplicats from        if self.no_duplicates:            seen = set()            new_triplets = []            for triplet in self.triplets:                if triplet['candidate'] not in seen:                    seen.add(triplet['candidate'])                    new_triplets.append(triplet)            self.triplets = new_triplets        # get the image names        self.image_names: list = []        for dress_type in dress_types:            with open(dataset_path / 'FASHIONIQ' / 'image_splits' / f'split.{dress_type}.{split}.json') as f:                self.image_names.extend(json.load(f))        print(f"FashionIQ {split} - {dress_types} dataset in {mode} mode initialized")    def __getitem__(self, index) -> dict:        try:            if self.mode == 'relative':                relative_captions = self.triplets[index]['captions']                reference_name = self.triplets[index]['candidate']                if self.split in ['train', 'val']:                    reference_image_path = self.dataset_path / 'FASHIONIQ' / 'images' / f"{reference_name}.png"                    reference_image = self.preprocess(PIL.Image.open(reference_image_path))                    target_name = self.triplets[index]['target']                    target_image_path = self.dataset_path / 'FASHIONIQ' / 'images' / f"{target_name}.png"                    target_image = self.preprocess(PIL.Image.open(target_image_path))                    if len(self.dress_types) != 1:                        mental_images = self.preprocess(                            PIL.Image.open(f'./data_CIR/FASHIONIQ/val_qwen_edit/{index}.png'))                        with open(f'./data_CIR/FASHIONIQ/val_qwen_edit_des/{index}.txt', 'r') as f:                            mental_images_des = f.read()                    else:                        mental_images = self.preprocess(PIL.Image.open(                            f'./data_CIR/FASHIONIQ/{self.dress_types[0]}_qwen_edit/{index}.png'))                        with open(f'./data_CIR/FASHIONIQ/{self.dress_types[0]}_qwen_edit_des/{index}.txt', 'r') as f:                            mental_images_des = f.read()                    return {                        'reference_image': reference_image,                        'reference_name': reference_name,                        'target_image': target_image,                        'mental_images': mental_images,                        'mental_images_des': mental_images_des,                        'target_name': target_name,                        'mod_text': relative_captions                    }            elif self.mode == 'classic':                image_name = self.image_names[index]                image_path = self.dataset_path / 'FASHIONIQ' / 'images' / f"{image_name}.png"                image = self.preprocess(PIL.Image.open(image_path))                synthetic_img = self.preprocess(                    PIL.Image.open(f'./data_CIR/FASHIONIQ/qwen_database_img/{image_name}.png'))                return {                    'image': image,                    'synthetic_img': synthetic_img,                    'image_name': image_name,                }            else:                raise ValueError("mode should be in ['relative', 'classic']")        except Exception as e:            print(f"Exception: {e}")    def __len__(self):        if self.mode == 'relative':            return len(self.triplets)        elif self.mode == 'classic':            return len(self.image_names)        else:            raise ValueError("mode should be in ['relative', 'classic']")class CIRRDataset(Dataset):    """   CIRR dataset class for PyTorch dataloader.   The dataset can be used in 'relative' or 'classic' mode:        - In 'classic' mode the dataset yield a dict with keys ['image', 'image_name']        - In 'relative' mode the dataset yield dict with keys:            - ['reference_image', 'reference_name', 'target_image', 'target_name', 'relative_caption', 'group_members']             when split in ['train', 'val']            - ['reference_image', 'reference_name' 'relative_caption', 'group_members', 'pair_id'] when split == test    """    def __init__(self, dataset_path: Union[Path, str], split: Literal['train', 'val', 'test'],                 mode: Literal['relative', 'classic'], preprocess: callable, no_duplicates: Optional[bool] = False):        """        :param dataset_path: path to the CIRR dataset        :param split: dataset split, should be in ['train', 'val', 'test']        :param mode: dataset mode, should be in ['relative', 'classic']:                - In 'classic' mode the dataset yield a dict with keys ['image', 'image_name']                - In 'relative' mode the dataset yield dict with keys:                    - ['reference_image', 'reference_name', 'target_image', 'target_name', 'relative_caption',                    'group_members'] when split in ['train', 'val']                    - ['reference_image', 'reference_name' 'relative_caption', 'group_members', 'pair_id'] when split == test        :param preprocess: function which preprocesses the image        :param no_duplicates: if True, the dataset will not yield duplicate images in relative mode, does not affect classic mode        """        dataset_path = Path(dataset_path)        self.dataset_path = dataset_path        self.preprocess = preprocess        self.mode = mode        self.split = split        self.no_duplicates = no_duplicates        if split == "test":            split = "test1"            self.split = "test1"        # Validate inputs        if split not in ['test1', 'train', 'val']:            raise ValueError("split should be in ['test1', 'train', 'val']")        if mode not in ['relative', 'classic']:            raise ValueError("mode should be in ['relative', 'classic']")        # get triplets made by (reference_image, target_image, relative caption)        with open(dataset_path / 'CIRR' / 'cirr' / 'captions' / f'cap.rc2.{split}.json') as f:            self.triplets = json.load(f)        # Remove duplicates from triplets        if self.no_duplicates:            seen = set()            new_triplets = []            for triplet in self.triplets:                if triplet['reference'] not in seen:                    seen.add(triplet['reference'])                    new_triplets.append(triplet)            self.triplets = new_triplets        # get a mapping from image name to relative path        with open(dataset_path / 'CIRR' / 'cirr' / 'image_splits' / f'split.rc2.{split}.json') as f:            self.name_to_relpath = json.load(f)        print(f"CIRR {split} dataset in {mode} mode initialized")    def __getitem__(self, index) -> dict:        try:            if self.mode == 'relative':                group_members = self.triplets[index]['img_set']['members']                reference_name = self.triplets[index]['reference']                relative_caption = self.triplets[index]['caption']                if self.split in ['train', 'val']:                    reference_image_path = self.dataset_path / 'CIRR' / self.name_to_relpath[reference_name]                    reference_image = self.preprocess(PIL.Image.open(reference_image_path))                    target_hard_name = self.triplets[index]['target_hard']                    target_image_path = self.dataset_path / self.name_to_relpath[target_hard_name]                    target_image = self.preprocess(PIL.Image.open(target_image_path))                    with open(f'{self.dataset_path}/CIRR/dev_qwen_pseudo_text/{str(index)}.txt', 'r') as f:                        mental_image_des = f.read()                    mental_image_path = f'{self.dataset_path}/CIRR/dev_qwen_pseudo_img/{str(index)}.png'                    mental_image = self.preprocess(PIL.Image.open(mental_image_path))                    return {                        'reference_image': reference_image,                        'mental_image': mental_image,                        'reference_name': reference_name,                        'target_image': target_image,                        'target_name': target_hard_name,                        'relative_caption': relative_caption,                        'mental_image_des': mental_image_des,                        'group_members': group_members                    }                elif self.split == 'test1':                    pair_id = self.triplets[index]['pairid']                    reference_image_path = self.dataset_path / 'CIRR' / self.name_to_relpath[reference_name]                    reference_image = self.preprocess(PIL.Image.open(reference_image_path))                    with open(f'{self.dataset_path}/CIRR/test1_qwen_edit_des_short/{str(index)}.txt', 'r') as f:                        mental_image_des = f.read()                    mental_image_path = f'{self.dataset_path}/CIRR/test1_qwen_edit/{str(index)}.png'                    mental_image = self.preprocess(PIL.Image.open(mental_image_path))                    return {                        'reference_image': reference_image,                        'mental_image': mental_image,                        'reference_name': reference_name,                        'relative_caption': relative_caption,                        'group_members': group_members,                        'pair_id': pair_id,                        'mental_image_des': mental_image_des,                    }            elif self.mode == 'classic':                image_name = list(self.name_to_relpath.keys())[index]                image_path = self.dataset_path / 'CIRR' / self.name_to_relpath[image_name]                im = PIL.Image.open(image_path)                image = self.preprocess(im)                synthetic_img_path = f'{self.dataset_path}/CIRR/qwen_index_images_2/{image_name}.png'                synthetic_img = PIL.Image.open(synthetic_img_path)                synthetic_img = self.preprocess(synthetic_img)                return {                    'image': image,                    'synthetic_img': synthetic_img,                    'image_name': image_name,                }            else:                raise ValueError("mode should be in ['relative', 'classic']")        except Exception as e:            print(f"Exception: {e}")    def __len__(self):        if self.mode == 'relative':            return len(self.triplets)        elif self.mode == 'classic':            return len(self.name_to_relpath)        else:            raise ValueError("mode should be in ['relative', 'classic']")class CIRCODataset(Dataset):    """    CIRCO dataset class for PyTorch.    The dataset can be used in 'relative' or 'classic' mode:        - In 'classic' mode the dataset yield a dict with keys ['image', 'image_name']        - In 'relative' mode the dataset yield dict with keys:            - ['reference_image', 'reference_name', 'target_image', 'target_name', 'relative_captions', 'shared_concept',             'gt_img_ids', 'query_id'] when split == 'val'            - ['reference_image', 'reference_name', 'relative_captions', 'shared_concept', 'query_id'] when split == test    """    def __init__(self, dataset_path: Union[str, Path], split: Literal['val', 'test'],                 mode: Literal['relative', 'classic'], preprocess: callable):        """        Args:            dataset_path (Union[str, Path]): path to CIRCO dataset            split (str): dataset split, should be in ['test', 'val']            mode (str): dataset mode, should be in ['relative', 'classic']            preprocess (callable): function which preprocesses the image        """        # Set dataset paths and configurations        dataset_path = Path(dataset_path)        self.mode = mode        self.split = split        self.preprocess = preprocess        self.data_path = dataset_path        # Ensure input arguments are valid        if mode not in ['relative', 'classic']:            raise ValueError("mode should be in ['relative', 'classic']")        if split not in ['test', 'val']:            raise ValueError("split should be in ['test', 'val']")        # Load COCO images information        with open(dataset_path / 'CIRCO' / 'COCO2017_unlabeled' / "annotations" / "image_info_unlabeled2017.json", "r") as f:            imgs_info = json.load(f)        self.img_paths = [dataset_path / 'CIRCO' / 'COCO2017_unlabeled' / "unlabeled2017" / img_info["file_name"] for img_info in                          imgs_info["images"]]        self.img_ids = [img_info["id"] for img_info in imgs_info["images"]]        self.img_ids_indexes_map = {str(img_id): i for i, img_id in enumerate(self.img_ids)}        # get CIRCO annotations        with open(dataset_path / 'CIRCO' / 'annotations' / f'{split}.json', "r") as f:            self.annotations: List[dict] = json.load(f)        # Get maximum number of ground truth images (for padding when loading the images)        self.max_num_gts = 23  # Maximum number of ground truth images        print(f"CIRCODataset {split} dataset in {mode} mode initialized")    def get_target_img_ids(self, index) -> Dict[str, int]:        """        Returns the id of the target image and ground truth images for a given query        Args:            index (int): id of the query        Returns:             Dict[str, int]: dictionary containing target image id and a list of ground truth image ids        """        return {            'target_img_id': self.annotations[index]['target_img_id'],            'gt_img_ids': self.annotations[index]['gt_img_ids']        }    def __getitem__(self, index) -> dict:        """        Returns a specific item from the dataset based on the index.        In 'classic' mode, the dataset yields a dictionary with the following keys: [img, img_id]        In 'relative' mode, the dataset yields dictionaries with the following keys:            - [reference_img, reference_img_id, target_img, target_img_id, relative_caption, shared_concept, gt_img_ids,            query_id]            if split == val            - [reference_img, reference_img_id, relative_caption, shared_concept, query_id]  if split == test        """        if self.mode == 'relative':            # Get the query id            query_id = str(self.annotations[index]['id'])            if self.split == 'val':                query_id = str(self.annotations[index]['id'])                # Get relative caption and shared concept                relative_caption = self.annotations[index]['relative_caption']                shared_concept = self.annotations[index]['shared_concept']                reference_img_id = str(self.annotations[index]['reference_img_id'])                with open(                        f'./data_CIR/CIRCO/COCO2017_unlabeled/val_modify_shared_generate_text/{reference_img_id}.txt',                        'r') as f:                    text_composed = f.read()                with open(                        f'./data_CIR/CIRCO/COCO2017_unlabeled/val_qwen_edit_des/{str(index)}.txt',                        'r') as f:                    mental_images_des = f.read()                # Get the reference image                reference_img_id = str(self.annotations[index]['reference_img_id'])                reference_img_path = self.img_paths[self.img_ids_indexes_map[reference_img_id]]                reference_img = self.preprocess(PIL.Image.open(reference_img_path))                mental_img = self.preprocess(PIL.Image.open(                    f'./data_CIR/CIRCO/COCO2017_unlabeled/val_qwen_edit/{str(index)}.png'))                # Get the target image and ground truth images                target_img_id = str(self.annotations[index]['target_img_id'])                gt_img_ids = [str(x) for x in self.annotations[index]['gt_img_ids']]                target_img_path = self.img_paths[self.img_ids_indexes_map[target_img_id]]                target_img = self.preprocess(PIL.Image.open(target_img_path))                # Pad ground truth image IDs with zeros for collate_fn                gt_img_ids += [''] * (self.max_num_gts - len(gt_img_ids))                return {                    'reference_image': reference_img,                    'reference_name': reference_img_id,                    'mental_images': mental_img,                    'target_image': target_img,                    'target_name': target_img_id,                    'relative_caption': relative_caption,                    'shared_concept': shared_concept,                    'gt_img_ids': gt_img_ids,                    'query_id': query_id,                    'mental_images_des': mental_images_des,                    'mod_text': text_composed                }            elif self.split == 'test':                # Get relative caption and shared concept                relative_caption = self.annotations[index]['relative_caption']                with open(                        f'./data_CIR/CIRCO/COCO2017_unlabeled/test_qwen_edit_des_with_shared_concept/{str(index)}.txt',                        'r') as f:                    mental_img_des = f.read()                # Get the reference image                reference_img_id = str(self.annotations[index]['reference_img_id'])                with open(                        f'./data_CIR/CIRCO/COCO2017_unlabeled/test_modify_shared_generate_text/{reference_img_id}.txt',                        'r') as f:                    text_composed = f.read()                reference_img_path = self.img_paths[self.img_ids_indexes_map[reference_img_id]]                reference_img = self.preprocess(PIL.Image.open(reference_img_path))                mental_img = self.preprocess(PIL.Image.open(                    f'./data_CIR/CIRCO/COCO2017_unlabeled/test_qwen_edit_with_shared_concept/{str(index)}.png'))                return {                    'reference_image': reference_img,                    'mental_img': mental_img,                    'reference_name': reference_img_id,                    'relative_caption': relative_caption,                    'mental_img_des': mental_img_des,                    'query_id': query_id,                    'text_composed': text_composed                }        elif self.mode == 'classic':            # Get image ID and image path            img_id = str(self.img_ids[index])            img_path = self.img_paths[index]            # Preprocess image and return            img = self.preprocess(PIL.Image.open(img_path))            synthetic_img = self.preprocess(PIL.Image.open(                f'./data_CIR/CIRCO/COCO2017_unlabeled/unlabeled2017_img/{str(img_path).split("/")[-1].split(".")[0]}.png'))            return {                'image': img,                'image_name': img_id,                'synthetic_img': synthetic_img,            }    def __len__(self):        """        Returns the length of the dataset.        """        if self.mode == 'relative':            return len(self.annotations)        elif self.mode == 'classic':            return len(self.img_ids)        else:            raise ValueError("mode should be in ['relative', 'classic']")class ImageNetDataset(Dataset):    """    Dataset class for ImageNet dataset    The dataset yields a dictionary with the following keys: ['image', 'image_name']    """    def __init__(self, dataset_path: Union[Path, str], split: Literal['train', 'val', 'test'], preprocess: callable):        dataset_path = Path(dataset_path)        self.dataset_path = dataset_path        self.split = split        self.preprocess = preprocess        if split not in ['train', 'val', 'test']:            raise ValueError("split should be in ['train', 'val', 'test']")        self.images_path = [p for p in (dataset_path / split).rglob("*.JPEG")]    def __getitem__(self, index) -> dict:        img_path = self.images_path[index]        img = self.preprocess(PIL.Image.open(img_path))        return {            'image': img,            'image_name': img_path.name        }    def __len__(self):        return len(self.images_path)